import json
import os
import sys
from datetime import datetime, timedelta
from collections import defaultdict

def parse_date(date_str):
    """Parse date from various formats in FDA data."""
    if not date_str or date_str.strip() == "":
        return None

    # Try common formats
    formats = ["%Y%m%d", "%Y%m%d", "%Y%m%d", "%Y%m%d"]  # All seem to be YYYYMMDD
    for fmt in formats:
        try:
            return datetime.strptime(date_str.strip(), fmt).date()
        except ValueError:
            continue

    # If we get here, try to clean and parse
    cleaned = date_str.strip().replace("/", "").replace("-", "")
    if len(cleaned) == 8 and cleaned.isdigit():
        try:
            return datetime.strptime(cleaned, "%Y%m%d").date()
        except ValueError:
            pass

    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data."""
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record

    return records

def process_pair(pair, facts, fda_records):
    """Process a single rule_id::entity pair."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    # Get the record for this entity
    record = fda_records.get(entity)

    for fact_name in facts[rule_id]:
        if fact_name == "initiation date":
            if not record:
                result[fact_name] = "ABSENT"
            else:
                date_str = record.get("recall_initiation_date", "")
                date_val = parse_date(date_str)
                if date_val:
                    result[fact_name] = [date_val.isoformat(), "fda_enforcement_reports"]
                else:
                    result[fact_name] = "ABSENT"

        elif fact_name == "classification date":
            if not record:
                result[fact_name] = "ABSENT"
            else:
                date_str = record.get("center_classification_date", "")
                date_val = parse_date(date_str)
                if date_val:
                    result[fact_name] = [date_val.isoformat(), "fda_enforcement_reports"]
                else:
                    result[fact_name] = "ABSENT"

        elif fact_name == "termination date":
            if not record:
                result[fact_name] = "ABSENT"
            else:
                date_str = record.get("termination_date", "")
                date_val = parse_date(date_str)
                if date_val:
                    result[fact_name] = [date_val.isoformat(), "fda_enforcement_reports"]
                else:
                    result[fact_name] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    # Load manifest
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, manifest["facts"], fda_records)

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

