import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date from various formats in FDA data."""
    if not date_str or date_str.strip() == "":
        return None
    # Remove any trailing spaces
    date_str = date_str.strip()
    # Try YYYYMMDD format (most common in this data)
    if len(date_str) == 8 and date_str.isdigit():
        try:
            return datetime.strptime(date_str, "%Y%m%d").date()
        except ValueError:
            pass
    # Try YYYY-MM-DD format
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        pass
    # Try other common formats
    for fmt in ["%m/%d/%Y", "%b %d, %Y", "%B %d, %Y"]:
        try:
            return datetime.strptime(date_str, fmt).date()
        except ValueError:
            continue
    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create a mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "").strip()
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value based on rule and fact name."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return date_str
        elif fact_name == "classification date":
            date_str = record.get("center_classification_date", "")
            return date_str
    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return date_str
        elif fact_name == "termination date":
            date_str = record.get("termination_date", "")
            return date_str
    return None

def process_pair(pair, fda_records, facts_map):
    """Process a single rule_id::entity pair."""
    rule_id, entity = pair.split("::", 1)
    facts = facts_map[rule_id]

    result = {}

    # Get the record for this entity
    record = fda_records.get(entity)

    if not record:
        # If no record found, all facts are ABSENT
        for fact in facts:
            result[fact] = "ABSENT"
        return result

    # For each fact, extract value
    fact_values = {}
    for fact in facts:
        value = extract_fact_value(record, fact, rule_id)
        fact_values[fact] = value

    # Check for conflicts (multiple values for same fact across different records)
    # In this case, we only have one record per entity, so no conflicts
    # But we need to handle missing values

    for fact in facts:
        value = fact_values[fact]
        if value is None or value == "":
            result[fact] = "ABSENT"
        else:
            # Parse date to ensure proper format
            parsed_date = parse_date(value)
            if parsed_date:
                formatted_date = parsed_date.strftime("%Y-%m-%d")
                result[fact] = [formatted_date, "fda_enforcement_reports"]
            else:
                # If can't parse as date, return as-is
                result[fact] = [value, "fda_enforcement_reports"]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    # Load manifest
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        result = process_pair(pair, fda_records, manifest["facts"])
        output[pair] = result

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

