import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in various formats to YYYY-MM-DD format."""
    if not date_str or date_str.strip() == "":
        return None

    # Clean the string
    date_str = date_str.strip()

    # Try YYYYMMDD format (most common in this data)
    if len(date_str) == 8 and date_str.isdigit():
        try:
            dt = datetime.strptime(date_str, "%Y%m%d")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    # Try other formats if needed (though not in current data)
    formats = ["%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y"]
    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            continue

    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def process_pair(pair, facts, fda_records):
    """Process a single pair (rule_id::entity) and return facts dict."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    for fact_name in facts[rule_id]:
        if rule_id == "fda.classified_30d":
            if fact_name == "initiation date":
                value = fda_records.get(entity, {}).get("recall_initiation_date")
                if value is None or value == "":
                    result[fact_name] = "ABSENT"
                else:
                    formatted_date = parse_date(value)
                    if formatted_date:
                        result[fact_name] = [formatted_date, "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"
            elif fact_name == "classification date":
                value = fda_records.get(entity, {}).get("center_classification_date")
                if value is None or value == "":
                    result[fact_name] = "ABSENT"
                else:
                    formatted_date = parse_date(value)
                    if formatted_date:
                        result[fact_name] = [formatted_date, "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

        elif rule_id == "fda.terminated_180d":
            if fact_name == "initiation date":
                value = fda_records.get(entity, {}).get("recall_initiation_date")
                if value is None or value == "":
                    result[fact_name] = "ABSENT"
                else:
                    formatted_date = parse_date(value)
                    if formatted_date:
                        result[fact_name] = [formatted_date, "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"
            elif fact_name == "termination date":
                value = fda_records.get(entity, {}).get("termination_date")
                if value is None or value == "":
                    result[fact_name] = "ABSENT"
                else:
                    formatted_date = parse_date(value)
                    if formatted_date:
                        result[fact_name] = [formatted_date, "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, manifest["facts"], fda_records)

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

