import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date from various formats (YYYYMMDD, empty, etc.) to datetime.date or None."""
    if not date_str or date_str.strip() == "":
        return None
    # Remove any whitespace
    date_str = date_str.strip()
    # Try common formats
    try:
        # Format YYYYMMDD
        if len(date_str) == 8 and date_str.isdigit():
            return datetime.strptime(date_str, "%Y%m%d").date()
        # Format YYYY-MM-DD (though not in this data)
        elif len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
            return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        pass
    return None

def load_fda_reports(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    # Create mapping from recall_number to record(s)
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            # Some recall numbers appear multiple times (different products)
            if recall_num not in records:
                records[recall_num] = []
            records[recall_num].append(record)
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on rule and fact name."""
    # Mapping from fact name to field name based on rules
    field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }
    field = field_map.get(fact_name)
    if not field:
        return None
    value = record.get(field, "")
    return value

def resolve_facts_for_entity(records, rule_id, fact_names):
    """Resolve all facts for an entity (recall number) across its records."""
    fact_values = {}
    documents = {}

    for fact_name in fact_names:
        values = set()
        docs = set()
        for record in records:
            value = extract_fact_value(record, fact_name, rule_id)
            if value and value.strip() and value != "N/A":
                # Parse to check if it's a valid date
                parsed = parse_date(value)
                if parsed:
                    # Format as YYYY-MM-DD
                    formatted = parsed.strftime("%Y-%m-%d")
                    values.add(formatted)
                    docs.add("fda_enforcement_reports")
                else:
                    # Not a date, keep as-is (though shouldn't happen for these facts)
                    values.add(value)
                    docs.add("fda_enforcement_reports")

        if not values:
            fact_values[fact_name] = "ABSENT"
        elif len(values) == 1:
            fact_values[fact_name] = [list(values)[0], list(docs)[0]]
        else:
            fact_values[fact_name] = "CONFLICT"

    return fact_values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load FDA reports
    fda_records = load_fda_reports(packet_dir)

    # Process each pair
    result = {}
