import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if fact_name == "initiation date":
        date_str = record.get("recall_initiation_date", "")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj:
            return [date_obj.isoformat(), "fda_enforcement_reports"]
        return "ABSENT"

    elif fact_name == "classification date":
        date_str = record.get("center_classification_date", "")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj:
            return [date_obj.isoformat(), "fda_enforcement_reports"]
        return "ABSENT"

    elif fact_name == "termination date":
        date_str = record.get("termination_date", "")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj:
            return [date_obj.isoformat(), "fda_enforcement_reports"]
        return "ABSENT"

    return "ABSENT"

def process_manifest(packet_dir, manifest_path):
    """Process manifest and extract required facts."""
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Initialize result structure
    result = {}

    # Process each pair
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)

        if entity not in fda_records:
            # Entity not found in records
            fact_names = facts_by_rule.get(rule_id, [])
            result[pair] = {fact: "ABSENT" for fact in fact_names}
            continue

        record = fda_records[entity]
        fact_names = facts_by_rule.get(rule_id, [])

        # For each fact, extract value
        pair_result = {}
        for fact_name in fact_names:
            value = extract_fact_value(record, fact_name, rule_id)
            pair_result[fact_name] = value

        result[pair] = pair_result

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    result = process_manifest(packet_dir, manifest_path)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

